        <select v-model="selectedVersion" @change="onVersionChange" class="version-select">
          <option
            v-for="v in versions"
            :key="v.buildNum"
            :value="v.buildNum === latestBuildNum ? '' : v.buildNum"
          >
            #{{ v.buildNum }} {{ v.tag }}{{ v.buildNum === latestBuildNum ? '(latest)' : '' }} — {{ formatDate(v.publishedAt) }}
          </option>
        </select>
        <!-- SDK 版本 + commit 信息合并 hover 区 -->
        <div
          class="version-info"
          v-if="currentRecord"
          @mouseenter="showChangelog = true"
          @mouseleave="showChangelog = false"
        >
          <span class="version-info-sdk">SDK {{ currentRecord.sdkVersion }}</span>
          <svg
