<script setup lang="ts">
/**
 * @changelog
 * | 版本   | 变更说明                                                | 关联                    |
 * | v1.1.0 | 版本切换行增加 SDK 版本展示 + changelog hover 浮层       | REQ: 版本管理与快速切换 |
 * | v1.2.0 | hover 浮层改用 commitMessage 替代 changelog 数组          | REQ: 版本管理与快速切换 |
 * | v2.0.0 | buildNum 替代 tag 作为主标识；展示 #buildNum tag 格式      | REQ: 版本管理与快速切换 |
 * /@changelog
 *
 * @author v_djlzhou
 */

import { ref, computed, onMounted, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { buildRouteLocation, fetchSceneConfig } from '../utils/route-params';
import { fetchVersions, getCurrentVersion, switchVersion } from '../utils/versions';
import type { VersionRecord } from '../utils/versions';

const router = useRouter();
const modelList = ref([]);
const modelUrl = ref('');

const STORAGE_KEY = 'viewer_showDebugViewer';

// 从 localStorage 恢复 Debug 开关状态，默认关闭
function loadShowDebugViewer() {
  try {
    return localStorage.getItem(STORAGE_KEY) === 'true';
  } catch {
    return false;
  }
}

const useSceneViewer = ref(true); // false: 元宇宙查看器, true: 场景查看器
const showDebugViewer = ref(loadShowDebugViewer()); // 是否在查看器中展示 Debug 工具面板

// 开关变化时持久化到 localStorage
watch(showDebugViewer, (val) => {
  try {
    localStorage.setItem(STORAGE_KEY, String(val));
  } catch {
    // 忽略存储异常
  }
});

// ── 版本管理 ──────────────────────────────────────────
const versions = ref<VersionRecord[]>([]);
const latestBuildNum = ref('');
const selectedVersion = ref('');
const currentVersion = ref('latest');

// 当前选中版本对应的完整记录（展示 sdkVersion / commitMessage）
const currentRecord = computed(() => {
  const num = selectedVersion.value || latestBuildNum.value;
  return versions.value.find((v) => v.buildNum === num) ?? null;
});

// changelog 浮层显隐（hover 触发）
const showChangelog = ref(false);

function formatDate(iso: string): string {
  if (!iso) return '';
  const d = new Date(iso);
  return `${d.getMonth() + 1}/${d.getDate()} ${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

function onVersionChange() {
  switchVersion(selectedVersion.value || null);
}

onMounted(async () => {
  // 并行加载场景配置和版本清单
  await Promise.all([
    (async () => {
      try {
        // 走 fetchSceneConfig 包装：URL 稳定 + cache:'no-cache' 防偶现 CORS（详见 route-params.ts v4.3.0）
        const requestFile = await fetchSceneConfig();

        if (requestFile.status !== 200) {
          throw new Error(`加载失败: ${requestFile.statusText}`);
        }

        const content = await requestFile.json();
        // COS JSON 是直接数组，无极 API 返回 { data: [...] }，兼容两种格式
        modelList.value = Array.isArray(content) ? content : content.data;
        console.log('成功加载场景配置:', content);
      } catch (error) {
        console.error('加载场景配置失败:', error);
      }
    })(),
    (async () => {
      try {
        const data = await fetchVersions();
        if (data && data.versions.length > 0) {
          versions.value = data.versions;
          latestBuildNum.value = data.latest;
          currentVersion.value = getCurrentVersion();
          selectedVersion.value = currentVersion.value === 'latest' ? '' : currentVersion.value;
          
        }
      } catch (error) {
        console.error('加载版本清单失败:', error);
      }
    })(),
  ]);
  // document.addEventListener('touchmove', touchHandler, { passive: false });
});
function goToModel(itemInfo) {
  // 优先使用 siteUri（.site 结尾）走 SiteUri 模式跳转
  const siteUri = itemInfo.siteUri || itemInfo.siteUrl || itemInfo.uri || itemInfo.site || '';
  if (siteUri && siteUri.endsWith('.site')) {
    const routeParams = { sceneUrl: siteUri };
    if (showDebugViewer.value) routeParams.showDebugViewer = 'true';
    console.log('使用 SiteUri 跳转:', siteUri);
    const { segments, query } = buildRouteLocation(routeParams);
    router.push({ name: 'siteScene', params: { segments }, query });
    return;
  }
  // 回退：使用普通 sceneUrl 走 viewer2 路由
  const routeName = 'viewer2';
  const sceneUrl = useSceneViewer.value ? itemInfo.modelUrlV2 : itemInfo.modelUrl;
  const routeParams = { sceneUrl };
  if (showDebugViewer.value) routeParams.showDebugViewer = 'true';
  console.log('使用的URL:', sceneUrl, '查看器类型:', useSceneViewer.value ? '场景查看器' : '元宇宙查看器');
  const { segments, query } = buildRouteLocation(routeParams);
  router.push({ name: routeName, params: { segments }, query });
}
const goToViewer = () => {
  const inputValue = modelUrl.value.trim();
  if (inputValue) {
    // siteUri（.site 结尾）走不带 /viewer2 前缀的 siteScene 路由
    const routeName = inputValue.endsWith('.site') ? 'siteScene' : 'viewer2';
    const routeParams = { sceneUrl: inputValue };
    if (showDebugViewer.value) routeParams.showDebugViewer = 'true';
    const { segments, query } = buildRouteLocation(routeParams);
    router.push({ name: routeName, params: { segments }, query });
  }
};
</script>
